// Kommentare normalisieren — nur neue (letzte 15 Minuten)
const data = items[0].json;
if (!data.items || data.items.length === 0) return [];

const cutoff = new Date(Date.now() - 16 * 60 * 1000); // 16 min Puffer
const results = [];

for (const thread of data.items) {
  const snippet = thread.snippet?.topLevelComment?.snippet || {};
  const publishedAt = new Date(snippet.publishedAt || 0);
  if (publishedAt < cutoff) continue; // Bereits verarbeiteter Kommentar

  results.push({
    json: {
      platform:     'youtube',
      platform_id:  thread.id || '',
      event_type:   'comment',
      author:       snippet.authorDisplayName || '',
      author_email: snippet.authorChannelUrl || '',
      subject:      'YouTube Kommentar auf: ' + (snippet.videoId || ''),
      content:      snippet.textOriginal || snippet.textDisplay || '',
      video_id:     snippet.videoId || '',
      comment_id:   thread.snippet?.topLevelComment?.id || '',
      like_count:   snippet.likeCount || 0,
      timestamp:    snippet.publishedAt || new Date().toISOString()
    }
  });
}

if (results.length === 0) {
  console.log('[YouTube Listener] Keine neuen Kommentare.');
  return [];
}
return results;

